export const BODY: string = "\n<p>ویب سائٹ سے ڈاؤن لوڈ شدہ WebP تصویر اکثر اس ایپ میں کھلنے سے انکار کر دیتی ہے جس میں آپ کو چاہیے۔ اسے JPG میں بدلنے میں ایک منٹ سے کم لگتا ہے، اور نتیجہ ہر جگہ کام کرتا ہے۔</p>\n<p>صرف مشکل حصہ شفافیت ہے۔ JPG شفاف پکسل محفوظ نہیں کر سکتا، اس لیے بدلنے سے پہلے ان کے لیے بھرنے والا رنگ چننا ہوتا ہے۔</p>\n<p>یہ رہنما WebP سے JPG تبدیلی کا ہر مرحلہ واضح کرتا ہے، تاکہ آپ کی پہلی کوشش میں ہی تصویر صاف اور درست بنے۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: شفافیت جانچیں</h2>\n<p>WebP کھولیں اور اس کا پس منظر دیکھیں۔ تصویر میں شفافیت نہیں ہوتی، اس لیے آپ بھرنے والے رنگ کے بارے میں سوچے بغیر بدل سکتے ہیں۔</p>\n<p>لوگو، اسٹیکر یا مصنوعات کی کٹ آؤٹ میں شاید شفافیت ہو۔ شفاف حصوں کو میٹ رنگ چاہیے ہوگا، اور آپ کو شروع کرنے سے پہلے طے کرنا چاہیے کہ کون سا۔</p>\n<p>سفید زیادہ تر منزلوں کو سوٹ کرتا ہے۔ دستاویزات، ویب صفحے اور فارم عام طور پر سفید پر بیٹھتے ہیں، اس لیے سفید میٹ وہاں قدرتی لگتا ہے۔</p>\n<h2 id=\"step-1-open-tool\">مرحلہ 1: WebP سے JPG ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/webp-ko-jpg-mein-convert-karein/\">WebP to JPG ٹول</a> کھولیں۔ یہ صفحہ ونڈوز، میک، لینکس، کروم او ایس، اینڈرائیڈ اور آئی او ایس پر کام کرتا ہے، بغیر کچھ انسٹال کیے۔</p>\n<p>آپ کو اپ لوڈ والا حصہ، میٹ رنگ چننے والا اور کوالٹی سلائیڈر دکھائی دے گا۔ یہ تین کنٹرول ہی پورا کام ہیں۔</p>\n<p>اکاؤنٹ کی ضرورت نہیں ہے، اور کچھ بھی اپ لوڈ نہیں ہوتا۔ تبدیلی آپ کے آلے پر ہوتی ہے، جو ذاتی تصویروں اور ڈاؤن لوڈ شدہ فائلوں کے لیے اہم ہے۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: اپنی WebP فائلیں اپ لوڈ کریں</h2>\n<p>اپنی WebP فائلیں اپ لوڈ والے حصے پر گھسیٹ دیں، یا فائل پکر کھولنے کے لیے اس پر کلک کریں۔ بیچ کے لیے کئی فائلیں ایک ساتھ چن سکتے ہیں۔</p>\n<p>WebP سے JPG میں بدلنے والی ہر فائل کارڈ کی صورت میں تھمب نیل، ابعاد اور سائز سمیت دکھائی دیتی ہے، تاکہ ایک ہی نظر میں تصدیق ہو جائے کہ صرف مطلوبہ فائلیں لوڈ ہوئی ہیں۔</p>\n<p>کچھ ویب سائٹس تصویریں بغیر فائل ایکسٹینشن کے محفوظ کرتی ہیں۔ وہ فائلیں پھر بھی بدلتی ہیں، کیونکہ ٹول نام پر بھروسے کی بجائے اصل مواد پڑھتا ہے۔</p>\n<h2 id=\"step-3-matte-colour\">مرحلہ 3: میٹ رنگ چنیں</h2>\n<p>شفاف حصوں کے بھرنے کے لیے میٹ رنگ چننے والے پر کلک کریں۔ سفید پہلے سے طے شدہ ہے اور زیادہ تر استعمال کو سوٹ کرتا ہے۔</p>\n<p>گہرے ڈیزائن کے لیے کالا چنیں، یا کسی مخصوص ویب سائٹ پس منظر سے بالکل ملانے کے لیے ہیکس کوڈ لکھیں۔ ملا ہوا پس منظر لوگو کو وہاں کا حصہ دکھاتا ہے۔</p>\n<p>اگر آپ کی WebP میں شفافیت نہیں ہے تو یہ ترتیب کچھ نہیں کرتی۔ تصویریں جو بھی رنگ چنیں، ویسے ہی گزر جاتی ہیں۔</p>\n<h2 id=\"step-4-quality\">مرحلہ 4: کوالٹی سلائیڈر طے کریں</h2>\n<p>کوالٹی سلائیڈر کنٹرول کرتا ہے کہ JPG انکوڈر کتنی تفصیل رکھتا ہے۔ زیادہ تر تصویروں کے لیے 85 فیصد بہترین نقطہ ہے۔</p>\n<p>پرنٹ جانے والی تصویروں کے لیے 90 فیصد یا زیادہ استعمال کریں۔ پرنٹ وہ خامیاں دکھاتا ہے جو اسکرین چھپاتی ہے، اور ایک اہم تصویر کے لیے اضافی سائز سستا ہے۔</p>\n<p>متن والے اسکرین شاٹ کے لیے کوالٹی 85 فیصد یا اوپر پر بھی رکھیں۔ چھوٹے حروف کم کوالٹی پر دھندلے ہو جاتے ہیں، اور دھندلا اسکرین شاٹ غیر پیشہ ورانہ لگتا ہے۔</p>\n<h2 id=\"step-5-convert-preview\">مرحلہ 5: بدلیں اور نتیجہ کا پیش نظارہ دیکھیں</h2>\n<p>Convert بٹن پر کلک کریں۔ ہر فائل الگ بدلتی ہے، اس لیے آپ پیش رفت کارڈ بہ کارڈ دیکھ سکتے ہیں۔</p>\n<p>ہر کارڈ پرانی WebP سائز کے ساتھ نیا JPG سائز دکھاتا ہے۔ JPG بڑی ہونے کی توقع رکھیں، کیونکہ WebP JPG سے زیادہ مؤثر ہے۔</p>\n<p>نتیجہ ساتھ ساتھ جانچنے کے لیے کسی کارڈ پر Compare پر کلک کریں۔ اسپلٹ ہینڈل تصویر پر گھسیٹیں اور متن، کنارے اور میٹ بھرنا زوم کر کے دیکھیں۔</p>\n<h2 id=\"step-6-download\">مرحلہ 6: JPG فائلیں ڈاؤن لوڈ کریں</h2>\n<p>WebP سے بنی JPG محفوظ کرنے کے لیے متعلقہ کارڈ پر Download دبائیں۔ فائل آپ کا اصل نام ہی رکھتی ہے، صرف آخر میں .jpg لگ جاتا ہے۔</p>\n<p>بیچ کے لیے Download All پر کلک کر کے ایک ZIP لیں جس میں ہر بدلی ہوئی JPG ہو۔ یہ ایک ایک کر کے ڈاؤن لوڈ کرنے سے کہیں تیز ہے۔</p>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائلیں ایک بار جانچیں۔ JPG اپنے فوٹو ویور میں کھولیں، یقین کریں کہ وہ درست لگتی ہے اور اس ایپ میں کھلتی ہے جسے اس کی ضرورت ہے۔</p>\n<ol>\n<li>WebP سے JPG ٹول کھولیں اور اپنی WebP فائلیں اپ لوڈ کریں۔</li>\n<li>شفاف حصوں کے لیے میٹ رنگ چنیں۔</li>\n<li>کوالٹی سلائیڈر 85 فیصد پر طے کریں۔</li>\n<li>بدلیں، Compare سے پیش نظارہ دیکھیں، پھر JPG ڈاؤن لوڈ کریں۔</li>\n</ol>\n<h2 id=\"converting-a-batch\">ڈاؤن لوڈ کا بیچ بدلنا</h2>\n<p>فائل پکر میں کئی WebP فائلیں ایک ساتھ چنیں۔ وہ سب قطار میں لوڈ ہو جاتی ہیں، اور ایک کلک سے سب JPG میں بدل جاتی ہیں۔</p>\n<p>پورے بیچ کے لیے ایک ہی میٹ رنگ اور کوالٹی استعمال کریں۔ مستقل مزاجی اہم ہے جب تصویریں ایک ہی دستاویز یا پراجیکٹ سے تعلق رکھتی ہوں۔</p>\n<p>WebP سے JPG کی بیچ تبدیلی کے دوران خراب فائل پر انتباہ ظاہر ہوتا ہے، مگر باقی فائلیں رکتی نہیں، اس لیے درست تصاویر پھر بھی مکمل ہو جاتی ہیں۔</p>\n<h2 id=\"white-background-trick\">خالص سفید پس منظر لینے کی ترکیب</h2>\n<p>سفید پس منظر چاہنے والے لوگو کے لیے میٹ رنگ خالص سفید طے کریں، ہیکس کوڈ ffffff۔ یہ ہر شفاف حصے کو صاف سفید سے بھر دیتا ہے۔</p>\n<p>نتیجہ سفید صفحے کے خلاف جانچیں۔ لوگو بغیر کسی نظر آنے والے کنارے کے مل جانا چاہیے جہاں شفافیت تھی۔</p>\n<p>اگر لوگو میں نرم سائے ہوں تو وہ سفید پر چپٹے ہو جاتے ہیں۔ یہ متوقع ہے، کیونکہ JPG جزوی شفافیت محفوظ نہیں کر سکتا، اور نتیجہ پھر بھی صاف لگتا ہے۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر شفاف اسٹیکر کو کالا ڈبہ مل جائے تو میٹ رنگ کالا تھا یا طے نہیں ہوا تھا۔ اسے سفید یا اپنے صفحے کے رنگ پر بدلیں اور دوبارہ بدلیں۔</p>\n<p>اگر متن دھندلا لگے تو کوالٹی بہت کم تھی۔ سلائیڈر 90 فیصد پر بڑھائیں اور اصل WebP سے دوبارہ بدلیں۔</p>\n<p>اگر کوئی فائل بدلنے میں ناکام ہو تو جانچیں کہ یہ واقعی WebP ہے۔ بغیر ایکسٹینشن والی فائل بھیس میں JPG یا PNG ہو سکتی ہے، اور ٹول فیصلہ کرنے کے لیے مواد پڑھتا ہے۔</p>\n<h2 id=\"mobile-tips\">فون اور ٹیبلٹ کے لیے نکات</h2>\n<p>فون پر اپ لوڈ والے حصے پر ٹیپ کریں اور اپنے ڈاؤن لوڈ یا گیلری سے WebP فائلیں چنیں۔ تبدیلی فون پر چلتی ہے، اور JPG آپ کے آلے پر ڈاؤن لوڈ ہوتی ہیں۔</p>\n<p>فون کے بیچ چھوٹے رکھیں، کیونکہ بڑی WebP فائلیں موبائل پروسیسر پر ڈی کوڈ ہونے میں وقت لیتی ہیں۔ ایک وقت میں دس فائلیں آرام دہ ہیں۔</p>\n<p>WebP سے JPG میں بدلی تصویر آپ کے فون کے Downloads فولڈر میں اترتی ہے۔ آئی فون پر Files ایپ کھولیں، اینڈرائیڈ پر فائل مینیجر میں اسے تلاش کریں۔</p>\n<h2 id=\"converting-wallpapers\">ڈاؤن لوڈ شدہ وال پیپر بدلنا</h2>\n<p>ویب سائٹ سے ڈاؤن لوڈ شدہ وال پیپر اکثر WebP فائلیں ہوتے ہیں، اور انہیں پرانے نظام پر ڈیسک ٹاپ پس منظر کے طور پر استعمال کرنے سے پہلے بدلنا ہوتا ہے۔ JPG وال پیپر ہر جگہ کام کرتا ہے۔</p>\n<p>وال پیپر کو 90 فیصد کوالٹی پر JPG میں بدلیں۔ تصویر اسکرین بھرتی ہے، رنگ بھرپور رہتے ہیں اور فائل کسی بھی آپریٹنگ سسٹم پر پس منظر کے طور پر کھلتی ہے۔</p>\n<p>بدلنے سے پہلے ابعاد جانچیں۔ وال پیپر آپ کی اسکرین ریزولوشن سے میل کھانا چاہیے، اور بڑی اسکرین پر کھینچی گئی چھوٹی تصویر فارمیٹ سے قطع نظر دھندلی لگتی ہے۔</p>\n<h2 id=\"webp-school-project\">اسکول پراجیکٹ کے لیے WebP بدلنا</h2>\n<p>اسکول پراجیکٹ کو اکثر ویب سے تصویریں چاہییں ہوتی ہیں، اور وہ تصویریں عام طور پر WebP ہوتی ہیں۔ پرانے سافٹ ویئر والا اسکول کمپیوٹر انہیں نہیں دکھا سکتا، اس لیے پہلے JPG میں بدلیں۔</p>\n<p>پراجیکٹ میں شامل کرنے سے پہلے تصویروں کو 85 فیصد کوالٹی پر JPG میں بدلیں۔ JPG پاورپوائنٹ، ورڈ اور گوگل سلائیڈز میں صاف ایمبیڈ ہوتی ہیں، اور پراجیکٹ کسی بھی اسکول کمپیوٹر پر کھلتا ہے۔</p>\n<p>کئی تصویروں والے پراجیکٹ کے لیے پورا سیٹ ایک ساتھ بدلیں۔ بیچ تبدیلی میں منٹ لگتے ہیں، اور JPG سلائیڈوں میں ڈالنے کے لیے تیار ہوتی ہیں۔</p>\n<h2 id=\"webp-for-cv\">CV کے لیے WebP بدلنا</h2>\n<p>CV تصویر بھرتی کرنے والے کے کمپیوٹر پر کھلنی چاہیے، اور WebP تصویر ناکام ہو سکتی ہے۔ اسے CV میں شامل کرنے سے پہلے JPG میں بدلیں، اور نتیجہ احتیاط سے جانچیں۔</p>\n<p>آرام دہ تصویر کی بجائے پیشہ ورانہ ہیڈ شاٹ استعمال کریں۔ تصویر میں آپ کا چہرہ سادہ پس منظر کے خلاف صاف دکھائی دینا چاہیے، اچھی روشنی اور غیر جانبدار تاثر کے ساتھ۔</p>\n<p>تصویر کو 90 فیصد کوالٹی پر JPG میں بدلیں۔ چہرہ تیز رہتا ہے، رنگ قدرتی رہتے ہیں اور فائل بھرتی کرنے والے کو پیشہ ورانہ لگتی ہے۔</p>\n<h2 id=\"webp-for-printer\">پرنٹر کے لیے WebP بدلنا</h2>\n<p>پرنٹر JPG یا PNG کی توقع کرتے ہیں، اور پرنٹ شاپ کے نظام سے WebP فائل مسترد ہو سکتی ہے۔ فائل بھیجنے سے پہلے JPG میں بدلیں، اور پہلے شاپ کی شرائط جانچیں۔</p>\n<p>پرنٹ کے لیے کوالٹی 90 فیصد یا اوپر پر رکھیں۔ 6 بہ 4 انچ پر پرنٹ شدہ تصویر کو ہر پکسل تفصیل چاہیے ہوتی ہے، اور کم کوالٹی JPG کاغذ پر اپنی خامیاں دکھاتی ہے۔</p>\n<p>پرنٹ سے پہلے ابعاد جانچیں۔ 800 پکسل چوڑی ویب تصویر 3 انچ پر اچھی پرنٹ ہوتی ہے مگر 10 انچ پر خراب، اس لیے پرنٹ سائز کو پکسل گنتی سے ملائیں۔</p>\n<h2 id=\"webp-received-by-email\">ای میل سے ملی WebP بدلنا</h2>\n<p>تصویریں کبھی ای میل سے WebP منسلکات کے طور پر آتی ہیں، اور وہ وصول کنندہ کے فوٹو ویور میں کھلنے سے انکار کر دیتی ہیں۔ انہیں JPG میں بدلنے سے مسئلہ فوراً ٹھیک ہو جاتا ہے۔</p>\n<p>پہلے منسلکہ اپنے آلے پر محفوظ کریں، پھر اسے کنورٹر میں ڈالیں۔ ای میل ایپ سے سیدھا بدلنا شاذ ہی کام کرتا ہے، کیونکہ فائل آپ کے آلے پر موجود ہونی چاہیے۔</p>\n<p>محفوظ کرنے کے بعد تصویر کی کوالٹی جانچیں۔ ای میل خدمات کبھی منسلکات کمپریس کرتی ہیں، اس لیے محفوظ شدہ فائل اصل سے پہلے سے کم کوالٹی کی ہو سکتی ہے۔</p>\n<h2 id=\"webp-for-family-album\">خاندانی البم کے لیے WebP بدلنا</h2>\n<p>خاندانی البم کو ایسی تصویریں چاہییں جو ہر آلے پر کھلیں، اور WebP پرانے رشتہ دار کے فون پر ناکام ہو سکتی ہے۔ پہلے البم کو JPG میں بدلنے کا مطلب ہے کہ سب ایک جیسی تصویریں دیکھتے ہیں۔</p>\n<p>پورا البم ایک بیچ میں 85 فیصد کوالٹی پر بدلیں۔ تصویریں صاف لگتی ہیں، فائلیں ہر جگہ کھلتی ہیں اور البم پورے خاندان کے ساتھ شیئر کرنے کے لیے تیار ہوتا ہے۔</p>\n<p>پہلے تصویریں ترتیب دیں، دھندلے شاٹ اور نقل ہٹا دیں۔ تین سو تصویروں والے خاندانی البم میں اکثر پچاس رکھنے کے قابل ہوتی ہیں، اور صرف انہیں بدلنے سے حقیقی وقت بچتا ہے۔</p>\n<p>پورا طریقہ یہی ہے: اپ لوڈ کریں، میٹ چنیں، کوالٹی طے کریں، ڈاؤن لوڈ کریں۔ پس منظر کے لیے <a href=\"/ur/blog/webp-ko-jpg-rehnumai/\">WebP to JPG: Complete Guide</a> پڑھیں، اور مطابقت سوال کے لیے <a href=\"/ur/blog/webp-ko-jpg-compatibility/\">WebP to JPG: When Compatibility Beats Compression</a> دیکھیں۔ اگر آپ کو شفافیت رکھنی ہو تو <a href=\"/ur/webp-ko-png-mein-convert-karein/\">WebP to PNG کنورٹر</a> بہتر ٹول ہے۔</p>\n";

